for (const cell of LIM_ALL_CELLS) {
  const body = bodies[cell.id];
  if (!body) throw new Error(`Missing LIM body: ${cell.id}`);
  add(cell.content, ...body);
}

const fields = ['content', 'lookFor', 'question', 'next'];
const phrases = new Map(rows.map(([en,pt,nl]) => [en,[pt,nl]]));
const addPhrase = (en, pt, nl) => { add(en,pt,nl); phrases.set(en,[pt,nl]); };
for (const cell of LIM_INTRO_CELLS) {
  const values = intro[cell.id];
  if (!values || values.some(language => language.length !== fields.length)) throw new Error(`Incomplete intro: ${cell.id}`);
  fields.forEach((field,index) => addPhrase(cell[field], values[0][index], values[1][index]));
  const sections = [cell.content, `Explore · ${cell.topics.join(' · ')}`, `Look for · ${cell.lookFor}`, `Ask · ${cell.question}`, `Next · ${cell.next}`];
  const related = cell.relatedIds.map(id => LIM_INTRO_CELL_BY_ID[id].title);
  if (related.length) sections.push(`Connect · ${related.join(' · ')}`);
  const translated = [0,1].map(language => [
    values[language][0],
    `${trLabel('Explore',language)} · ${cell.topics.map(topic => trLabel(topic,language)).join(' · ')}`,
    `${trLabel('Look for',language)} · ${values[language][1]}`,
    `${trLabel('Ask',language)} · ${values[language][2]}`,
    `${trLabel('Next',language)} · ${values[language][3]}`,
    ...(related.length ? [`${trLabel('Connect',language)} · ${related.map(title => trLabel(title,language)).join(' · ')}`] : [])
  ]);
  sections.forEach((en,index) => addPhrase(en,translated[0][index],translated[1][index]));
  addPhrase(limLearningContent(cell.id).body,translated[0].join('\n\n'),translated[1].join('\n\n'));
}

for (const cell of [...LIM_ALL_CELLS, ...LIM_INTRO_CELLS]) {
  const content = limLearningContent(cell.id);
  const translatedTitle = [0,1].map(language => trLabel(cell.title,language));
  if (cell.layoutRole === 'intro') {
    addPhrase(cell.accessibilityLabel, `${translatedTitle[0]}: célula introdutória de aprendizagem`, `${translatedTitle[1]}: inleidende leercel`);
  } else if (cell.layoutRole === 'face') {
    addPhrase(cell.accessibilityLabel, `Face da LIM: ${translatedTitle[0]}`, `LIM-vlak: ${translatedTitle[1]}`);
  } else {
    const face = LIM_FACES.find(face => face.id === cell.primaryFaceId);
    addPhrase(cell.accessibilityLabel, `Célula de aprendizagem ${translatedTitle[0]} em ${trLabel(face.title,0)}`, `Leercel ${translatedTitle[1]} in ${trLabel(face.title,1)}`);
  }
  const parts = content.breadcrumb.split(' · ');
  addPhrase(content.breadcrumb,parts.map(part => trLabel(part,0)).join(' · '),parts.map(part => trLabel(part,1)).join(' · '));
  addPhrase(content.sketchImageAlt, `Esboço conceptual a preto e branco de ${translatedTitle[0]}`, `Zwart-witte conceptschets voor ${translatedTitle[1]}`);
}

