moduleSteps.forEach(([title,message,cell],index) => {
  const step = index % 3 + 1;
  const count = 3;
  const headings = [`Micro step ${step} of ${count} · ${title}`,`Pequeno passo ${step} de ${count} · ${phrases.get(title)[0]}`,`Kleine stap ${step} van ${count} · ${phrases.get(title)[1]}`];
  addPhrase(...headings);
  const instructions = [`Select the highlighted ${cell} cell to continue.`, `Selecione a célula ${trLabel(cell,0)} destacada para continuar.`, `Selecteer de gemarkeerde cel ${trLabel(cell,1)} om verder te gaan.`];
  addPhrase(...instructions);
  addPhrase(`${headings[0]}\n\n${message}\n\n${instructions[0]}`, `${headings[1]}\n\n${phrases.get(message)[0]}\n\n${instructions[1]}`, `${headings[2]}\n\n${phrases.get(message)[1]}\n\n${instructions[2]}`);
  addPhrase(`Select ${cell} to continue. To finish, open Tools in the Control panel and choose End learning.`, `Selecione ${trLabel(cell,0)} para continuar. Para terminar, abra Ferramentas no Painel de controlo e escolha Terminar aprendizagem.`, `Selecteer ${trLabel(cell,1)} om verder te gaan. Open om af te ronden Gereedschap in het Bedieningspaneel en kies Leren beëindigen.`);
});
for (let step=1;step<=4;step++) addPhrase(`LEARNING 2.${step}`, `APRENDIZAGEM 2.${step}`, `LEREN 2.${step}`);

// Preserve exact whitespace in source keys; the caller owns key normalisation.
const unique = new Map();
for (const row of rows) {
  const previous = unique.get(row[0]);
  if (previous && (previous[1] !== row[1] || previous[2] !== row[2])) throw new Error(`Conflicting learning translation: ${row[0]}`);
  unique.set(row[0],row);
}
export const DEMO_LEARNING_TRANSLATIONS = [...unique.values()];
